5 class otbn_env extends cip_base_env #(
6     .CFG_T              (otbn_env_cfg),
7     .COV_T              (otbn_env_cov),
8     .VIRTUAL_SEQUENCER_T(otbn_virtual_sequencer),
9     .SCOREBOARD_T       (otbn_scoreboard)
10   );
11   `uvm_component_utils(otbn_env)
12 
13   otbn_model_agent    model_agent;
14   otbn_trace_monitor  trace_monitor;
15   otbn_sideload_agent keymgr_sideload_agent;
16   otp_key_agent       key_agent;
17 
18   `uvm_component_new
19 
20   function void build_phase(uvm_phase phase);
21     super.build_phase(phase);
22 
23     cfg.mem_util = OtbnMemUtilMake(cfg.dut_instance_hier);
24     `DV_CHECK_FATAL(cfg.mem_util != null);
25 
26     model_agent = otbn_model_agent::type_id::create("model_agent", this);
27     uvm_config_db#(otbn_model_agent_cfg)::set(this, "model_agent*", "cfg", cfg.model_agent_cfg);
28     cfg.model_agent_cfg.en_cov = cfg.en_cov;
29 
30     // Get the OTP clk/rst interface
31     if (!uvm_config_db#(virtual clk_rst_if)::get(this, "", "otp_clk_rst_vif",
32         cfg.otp_clk_rst_vif)) begin
33       `uvm_fatal(`gfn, "failed to get otp_clk_rst_if from uvm_config_db")
34     end
35     cfg.otp_clk_rst_vif.set_freq_mhz(cfg.otp_freq_mhz);
36 
37     keymgr_sideload_agent = otbn_sideload_agent::type_id::create("keymgr_sideload_agent", this);
38     uvm_config_db#(otbn_sideload_agent_cfg)::set(
39       this, "keymgr_sideload_agent*", "cfg", cfg.keymgr_sideload_agent_cfg);
40 
41     key_agent = otp_key_agent::type_id::create("key_agent", this);
42     uvm_config_db#(otp_key_agent_cfg)::set(this, "key_agent", "cfg", cfg.key_cfg);
43     cfg.key_cfg.agent_type = push_pull_agent_pkg::PullAgent;
44     cfg.key_cfg.if_mode = dv_utils_pkg::Device;
45     // CDC synchronization between OTP and OTBN clock domains requires that the scrambling seed data
46     // should be held for at least a few cycles before it can be safely latched by the OTBN domain.
47     // Easy way to do this is just to force the push_pull_agent to hold the data until the next key
48     // request is sent out.
49     cfg.key_cfg.hold_d_data_until_next_req = 1'b1;
50     cfg.key_cfg.zero_delays = 1'b1;
51     cfg.key_cfg.en_cov = cfg.en_cov;
52 
53     if (!uvm_config_db#(virtual otbn_trace_if)::get(this, "", "trace_vif", cfg.trace_vif)) begin
54       `uvm_fatal(`gfn, "failed to get otbn_trace_if handle from uvm_config_db")
55     end
56     if (!uvm_config_db#(virtual otbn_loop_if)::get(this, "", "loop_vif", cfg.loop_vif)) begin
57       `uvm_fatal(`gfn, "failed to get otbn_loop_if handle from uvm_config_db")
58     end
59     if (!uvm_config_db#(virtual otbn_alu_bignum_if)::get(this, "", "alu_bignum_vif",
60                                                          cfg.alu_bignum_vif)) begin
61       `uvm_fatal(`gfn, "failed to get otbn_alu_bignum_if handle from uvm_config_db")
62     end
63     if (!uvm_config_db#(virtual otbn_controller_if)::get(this, "", "controller_vif",
64                                                          cfg.controller_vif)) begin
65       `uvm_fatal(`gfn, "failed to get otbn_controller_if handle from uvm_config_db")
66     end
67     if (!uvm_config_db#(virtual otbn_mac_bignum_if)::get(this, "", "mac_bignum_vif",
68                                                          cfg.mac_bignum_vif)) begin
69       `uvm_fatal(`gfn, "failed to get otbn_mac_bignum_if handle from uvm_config_db")
70     end
71     if (!uvm_config_db#(virtual otbn_rf_base_if)::get(this, "", "rf_base_vif",
72                                                       cfg.rf_base_vif)) begin
73       `uvm_fatal(`gfn, "failed to get otbn_rf_base_if handle from uvm_config_db")
74     end
75     if (!uvm_config_db#(virtual otbn_escalate_if)::get(this, "", "escalate_vif",
76                                                        cfg.escalate_vif)) begin
77       `uvm_fatal(`gfn, "failed to get otbn_escalate_if handle from uvm_config_db")
78     end
79     if (!uvm_config_db#(virtual otbn_rnd_if)::get(this, "", "rnd_vif",
80                                                   cfg.rnd_vif)) begin
81       `uvm_fatal(`gfn, "failed to get otbn_rnd_if handle from uvm_config_db")
82     end
83     if (!uvm_config_db#(virtual otbn_ssctrl_if)::get(this, "", "ssctrl_vif",
84                                                      cfg.ssctrl_vif)) begin
85       `uvm_fatal(`gfn, "failed to get otbn_ssctrl_if handle from uvm_config_db")
86     end
87     if (!uvm_config_db#(sram_ctrl_bkdr_util)::get(this, "", "imem_util", cfg.imem_util)) begin
88       `uvm_fatal(`gfn, "failed to get imem_util from uvm_config_db")
89     end
90     if (!uvm_config_db#(sram_ctrl_bkdr_util)::get(this, "", "dmem_util", cfg.dmem_util)) begin
91       `uvm_fatal(`gfn, "failed to get dmem_util from uvm_config_db")
92     end
93 
94     trace_monitor = otbn_trace_monitor::type_id::create("trace_monitor", this);
95     trace_monitor.cfg = cfg;
96     trace_monitor.cov = cov;
97   endfunction
98 
99   function void connect_phase(uvm_phase phase);
100     super.connect_phase(phase);
101     model_agent.monitor.analysis_port.connect(scoreboard.model_fifo.analysis_export);
102     trace_monitor.analysis_port.connect(scoreboard.trace_fifo.analysis_export);
103     cfg.scoreboard = scoreboard;
104     virtual_sequencer.key_sideload_sequencer_h = keymgr_sideload_agent.sequencer;
105 
106     // Configure the key sideload sequencer to use UVM_SEQ_ARB_STRICT_FIFO arbitration. This makes
107     // sure that we can inject our own sequence if we need to override the default for a bit.
108     keymgr_sideload_agent.sequencer.set_arbitration(UVM_SEQ_ARB_STRICT_FIFO);
109   endfunction
110 
111   function void final_phase(uvm_phase phase);
112     super.final_phase(phase);
113 
114     `DV_CHECK_FATAL(cfg.mem_util != null);
115     OtbnMemUtilFree(cfg.mem_util);
116     cfg.mem_util = null;
117   endfunction
118 
119 endclass
</code>
